function renderEmojiAsSvg(str) {
  if (!str) return str;
  let res = str;
  for (const [emoji, svgCode] of Object.entries(CUSTOM_SVGS)) {
    if (res.includes(emoji)) {
      res = res.split(emoji).join(svgCode);
    }
  }
  return res;
}

// DOM Element builder
function el(tag, css, html, cls) {
  const e = document.createElement(tag);
  if (css) e.style.cssText = css;
  if (html != null) e.innerHTML = renderEmojiAsSvg(String(html));
  if (cls) e.className = cls;
  return e;
}

// Pixel scaling based on zoom
function px(v, z) {
  return Math.round(v * z) + 'px';
}

// Animation styles generator
function as(anim, delay, z) {
  if (anim === 'none') return '';
  const dur = 600, ease = 'cubic-bezier(.22,1,.36,1)';
  const map = {
    'fade-up': `animation:fadeUp ${dur}ms ${ease} ${delay}ms both`,
    'slide-right': `animation:slideIn ${dur}ms ${ease} ${delay}ms both`,
    'type-in': `animation:typeIn ${dur + 200}ms ${ease} ${delay}ms both`,
    'scale-in': `animation:scaleIn ${dur}ms ${ease} ${delay}ms both`,
    'heading-reveal': `animation:headingReveal 800ms cubic-bezier(0.16,1,0.3,1) ${delay}ms both`,
  };
  return map[anim] || map['heading-reveal'];
}

// Hash string for deterministic random selections
function hashStr(str) {
  let h = 0;
  for (let i = 0; i < (str || '').length; i++) {
    h = ((h << 5) - h + str.charCodeAt(i)) | 0;
  }
  return Math.abs(h);
}

// Inline Markdown Formatting (bold, italics, code)
function parseInlineMarkdown(s) {
  let html = s;
  // Bold: **text**
  html = html.replace(/\*\*([\s\S]*?)\*\*/g, '<strong style="color:var(--accent);font-weight:700">$1</strong>');
  // Italics: *text* or _text_
  html = html.replace(/\*([\s\S]*?)\*/g, '<em style="font-style:italic;color:#CFCFC8">$1</em>');
  html = html.replace(/_([\s\S]*?)_/g, '<em style="font-style:italic;color:#CFCFC8">$1</em>');
  // Inline Code: `code`
  html = html.replace(/`([\s\S]*?)`/g, '<code style="font-family:\'JetBrains Mono\',monospace;background:rgba(255,255,255,0.08);padding:2px 6px;border-radius:4px;font-size:0.9em;color:#f8c57c;border:1px solid rgba(255,255,255,0.05)">$1</code>');
  return html;
}

// HTML Escaping
function escHtml(s) {
  const escaped = (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  const emojiParsed = typeof renderEmojiAsSvg === 'function' ? renderEmojiAsSvg(escaped) : escaped;
  return parseInlineMarkdown(emojiParsed);
}

// Simple Syntax Highlighter for Java
const KW = new Set([
  'public','private','protected','static','void','class','interface','abstract',
  'final','new','return','if','else','for','while','do','switch','case',
  'break','continue','try','catch','finally','throw','throws','import',
  'package','extends','implements','this','super','null','true','false',
  'var','int','long','boolean','String','List','Map','Set','Optional','Stream'
]);

function colorizeHtml(line) {
  if (!line.trim()) return '&nbsp;';
  const ci = line.indexOf('//');
  const eff = ci >= 0 ? line.slice(0, ci) : line, cmt = ci >= 0 ? line.slice(ci) : '';
  const tok = []; let j = 0;
  while (j < eff.length) {
    if (eff[j] === '"') {
      let k = j + 1;
      while (k < eff.length && eff[k] !== '"') k++;
      tok.push({ t: 'str', v: eff.slice(j, k + 1) });
      j = k + 1;
    }
    else if (eff[j] === '@') {
      let k = j + 1;
      while (k < eff.length && /\w/.test(eff[k])) k++;
      tok.push({ t: 'ann', v: eff.slice(j, k) });
      j = k;
    }
    else if (/\d/.test(eff[j]) && (j === 0 || !/\w/.test(eff[j - 1]))) {
      let k = j;
      while (k < eff.length && /[\d.L]/.test(eff[k])) k++;
      tok.push({ t: 'num', v: eff.slice(j, k) });
      j = k;
    }
    else if (/\w/.test(eff[j])) {
      let k = j;
      while (k < eff.length && /\w/.test(eff[k])) k++;
      const w = eff.slice(j, k);
      tok.push({ t: KW.has(w) ? 'kw' : 'id', v: w });
      j = k;
    }
    else {
      tok.push({ t: 'p', v: eff[j] });
      j++;
    }
  }
  const cols = { kw: '#c792ea', str: '#c3e88d', ann: '#f07178', num: '#f78c6c', id: '#a0b0c8', p: '#6b7090' };
  let html = '';
  tok.forEach(t => { html += `<span style="color:${cols[t.t] || '#a0b0c8'}">${escHtml(t.v)}</span>`; });
  if (cmt) html += `<span style="color:#4a5a3a">${escHtml(cmt)}</span>`;
  return html || '&nbsp;';
}

// Shared Code Card Component used by multiple renderers
function codeCard(title, code, acc, z) {
  const card = el('div', `background:#0d1117;border-radius:${px(10, z)};border:1px solid ${acc}30;display:flex;flex-direction:column;overflow:hidden;height:100%`);
  const tb = el('div', `background:#161b22;padding:${px(8, z)} ${px(14, z)};display:flex;align-items:center;gap:${px(7, z)};border-bottom:1px solid ${acc}20;flex-shrink:0`);
  ['#f87c7c', '#f8d07c', '#7cf8a0'].forEach(c => tb.appendChild(el('span', `width:${px(8, z)};height:${px(8, z)};border-radius:50%;background:${c};display:inline-block`)));
  tb.appendChild(el('span', `font-size:${px(11, z)};color:#5a6a50;font-family:'JetBrains Mono',monospace;margin-left:${px(4, z)}`, escHtml(title + '.java')));
  card.appendChild(tb);
  const body = el('div', `padding:${px(12, z)} ${px(14, z)};overflow:auto;flex:1`);
  (code || '').split('\n').forEach((line, i) => {
    const row = el('div', `display:flex;gap:${px(10, z)}`, '', 'code-line');
    row.dataset.idx = i;
    row.appendChild(el('span', `color:#3a3d52;min-width:${px(20, z)};text-align:right;flex-shrink:0;font-size:${px(11, z)};font-family:'JetBrains Mono',monospace;user-select:none`, i + 1));
    row.appendChild(el('span', `font-size:${px(11, z)};font-family:'JetBrains Mono',monospace;white-space:pre`, colorizeHtml(line)));
    body.appendChild(row);
  });
  card.appendChild(body);
  return card;
}

// Helper to get step-reveal items (bullets, code lines, step items)
function getRevealItems(target) {
  target = target || document.getElementById('slide-dom');
  const all = [...target.querySelectorAll('.bullet-item'), ...target.querySelectorAll('.code-line'), ...target.querySelectorAll('.step-item'), ...target.querySelectorAll('[data-step]')];
  all.sort((a, b) => parseInt(a.dataset.idx || '0') - parseInt(b.dataset.idx || '0'));
  return all;
}
